import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md","lastUpdated":1788432572000}`),a={name:`guide/getting-started.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to “Getting started”">​</a></h1><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to “Requirements”">​</a></h2><ul><li>Node.js ≥ 22</li><li>A running <a href="https://mealie.io" target="_blank" rel="noreferrer">Mealie</a> instance (verified against v3.25.0)</li><li>An API token from Mealie&#39;s <strong>Settings → API Tokens</strong> — see <a href="/guide/configuration">Configuration</a></li></ul><h2 id="run-it" tabindex="-1">Run it <a class="header-anchor" href="#run-it" aria-label="Permalink to “Run it”">​</a></h2><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">MEALIE_URL</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">https://mealie.example.com</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;"> MEALIE_API_TOKEN</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">…</span><span style="--shiki-light:#953800;--shiki-dark:#FFA657;"> npx</span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;"> -y</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> @ni-c/mealie-mcp</span></span></code></pre></div><p>The server speaks MCP over stdio, so it is normally started by an MCP client rather than by hand — see <a href="/guide/clients">Connecting clients</a> for the config snippets for Claude Code, Claude Desktop, Codex and others.</p><p>Without credentials the server still starts and lists its tools; every call then fails with setup instructions instead of reaching the API. This lets registries and inspectors introspect the tool catalog without a live instance.</p><h2 id="first-calls" tabindex="-1">First calls <a class="header-anchor" href="#first-calls" aria-label="Permalink to “First calls”">​</a></h2><p>A good smoke test once the server is connected:</p><ol><li><code>get_about</code> — reports the Mealie version and the identity the token acts as, including the permission flags that decide which write tools will succeed.</li><li><code>search_recipes</code> with a search term — returns recipe summaries.</li><li><code>get_recipe</code> with one of the returned slugs — returns the full recipe with ingredients and steps.</li></ol><h2 id="read-only-mode" tabindex="-1">Read-only mode <a class="header-anchor" href="#read-only-mode" aria-label="Permalink to “Read-only mode”">​</a></h2><p>Set <code>MEALIE_READ_ONLY=true</code> (exactly the string <code>true</code>) to register only the 17 read tools. The 34 write and import tools are not registered at all — a model cannot call what does not exist. Check the startup line on stderr, which reports the mode in effect.</p>`,12)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};